-- Type et modèles FR/EN du socle Documents pour la fiche d'orientation du secondaire DOC-16 (EX-PAS-03, catalogue de plateforme,
-- client « * ») : émise par le conseiller d'orientation depuis le dossier de l'élève [orientation], sans QR (CDC). Modèle neutre,
-- éditable par /document-templates : aucune note, aucune donnée de santé. HTML et CSS sans point-virgule.

INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT1600000000000000000', '*', '', 'sec_doc16_orientation_sheet', 'Fiche d’orientation (DOC-16)', 'other', 'O', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","wishes_block","counsellor_opinion","interview_on","decision_label","decision_reason"]', 'sec_chef_etablissement', '2026-11-08T04:03:00+01:00', '2026-11-08T04:03:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT16F0000000000000000', '*', '', 'sec_doc16_orientation_sheet', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:10px}</style><h1>{{establishment_name}}</h1><h2>Fiche d’orientation</h2><p>Année scolaire : {{academic_year}}</p><p>Élève : <strong>{{holder_name}}</strong>, classe {{class_name}}</p><p>Vœux de l’élève, par ordre de préférence :</p><pre>{{wishes_block}}</pre><p>Avis du conseiller d’orientation : {{counsellor_opinion}}</p><p>Entretien avec le conseiller : {{interview_on}}</p><p>Décision d’orientation : <strong>{{decision_label}}</strong></p><p>Motif : {{decision_reason}}</p><p>Fait le {{issued_on}}.</p><p>Le conseiller d’orientation, le chef d’établissement.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-08T04:03:00+01:00', NULL, '2026-11-08T04:03:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT16E0000000000000000', '*', '', 'sec_doc16_orientation_sheet', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:10px}</style><h1>{{establishment_name}}</h1><h2>Guidance record</h2><p>School year: {{academic_year}}</p><p>Student: <strong>{{holder_name}}</strong>, class {{class_name}}</p><p>Student’s wishes, in order of preference:</p><pre>{{wishes_block}}</pre><p>Guidance counsellor’s opinion: {{counsellor_opinion}}</p><p>Interview with the counsellor: {{interview_on}}</p><p>Guidance decision: <strong>{{decision_label}}</strong></p><p>Reason: {{decision_reason}}</p><p>Issued on {{issued_on}}.</p><p>The guidance counsellor, the head of school.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-08T04:03:00+01:00', NULL, '2026-11-08T04:03:00+01:00');
